INSERT INTO `bonk_glyph_locale` (`id`, `locale`, `name`, `description`, `drawback`)
VALUES
  (2, 'zhCN', '囤积者雕文', '拾取范围提高60%。强化效果的持续时间加倍。', ''),
  (5, 'zhCN', '喘息雕文', '当30码内有一个精英、小首领或首领死亡时，为你恢复30%最大生命值。', ''),
  (6, 'zhCN', '魔网雕文', '占领魔网的速度加倍。魔网提供的可选祝福由3个增至4个。', ''),
  (7, 'zhCN', '风怒雕文', '你的法术有30%几率施放两次。', ''),
  (8, 'zhCN', '嗜血雕文', '每击杀50个敌人，获得40%急速，持续8秒。', ''),
  (11, 'zhCN', '圣盾术雕文', '受到致命伤害时，改为将你的生命值恢复全满。每次远征限一次。', ''),
  (12, 'zhCN', '灵魂收割雕文', '每击杀50个敌人，你造成的伤害提高至三倍，持续2秒。', ''),
  (13, 'zhCN', '报复雕文', '你每缺少2%生命值，力量就提高1%。', ''),
  (15, 'zhCN', '赌徒雕文', '升级时提供的法术等级、宝箱中的卡片以及雕文选项的稀有度提高1级。', '升级时只提供2个选项。'),
  (16, 'zhCN', '逐风者雕文', '每3秒，闪电会打击最多5个附近敌人，造成相当于普通难度下普通敌人生命值60%的伤害。必定造成致命一击。', ''),
  (17, 'zhCN', '拉格纳罗斯雕文', '每6秒，一颗陨石砸向附近最大的敌群。', ''),
  (18, 'zhCN', '眩目神速雕文', '冲刺充能次数增加1次。冲刺的冷却时间缩短30%。', ''),
  (19, 'zhCN', '预知雕文', '每个阶段额外获得2次重选机会。', ''),
  (20, 'zhCN', '寻宝者雕文', '每2分钟，你附近会出现一个宝箱。', ''),
  (21, 'zhCN', '拾荒者雕文', '你击杀的精英会掉落一个强化效果。', ''),
  (22, 'zhCN', '天才雕文', '你的起手法术初始等级提高2级，造成的伤害提高25%。', ''),
  (23, 'zhCN', '野心雕文', '每当小首领出现时，都会额外多出现1个。小首领给予双倍奖励。', '小首领造成的伤害提高25%。'),
  (24, 'zhCN', '狩猎雕文', '精英数量加倍，每个精英给予三倍经验值。', '精英更多，危险也更多。'),
  (25, 'zhCN', '破釜沉舟雕文', '生命值低于50%时，急速提高40%，移动速度提高20%。', ''),
  (27, 'zhCN', '游牧者雕文', '移动时力量提高25%。', '受到生命伤害时，该效果反转为力量降低25%，持续5秒。被护盾吸收的伤害不计入。'),
  (28, 'zhCN', '占卜雕文', '升级时额外提供1个选项。', ''),
  (29, 'zhCN', '冰霜新星雕文', '敌人击中你时，冻结10码内的普通敌人，持续2秒。冷却时间15秒。', ''),
  (30, 'zhCN', '消失雕文', '冲刺后，你在1秒内免疫伤害，且你的下一个法术必定造成致命一击。', ''),
  (31, 'zhCN', '尸体爆炸雕文', '你击杀的敌人有15%几率发生爆炸，对6码内的敌人造成相当于其生命值40%的伤害。', ''),
  (32, 'zhCN', '斩杀雕文', '生命值低于15%的普通敌人会立即死亡。生命值低于30%的精英、小首领和首领受到的伤害提高25%。', ''),
  (33, 'zhCN', '顺劈斩雕文', '最后一击的溢出伤害会打击10码内最近的敌人。', ''),
  (34, 'zhCN', '多重射击雕文', '你的法术额外射出1发箭矢。', '你的法术造成的伤害降低15%。'),
  (35, 'zhCN', '回响雕文', '选择法术等级时，有25%几率额外提升1级。', ''),
  (36, 'zhCN', '点燃雕文', '致命一击会施加2层燃烧。', ''),
  (37, 'zhCN', '灵魂虹吸雕文', '每击杀500个敌人，力量提高1%。', ''),
  (38, 'zhCN', '影之哀伤雕文', '每击杀50个敌人，你收集的灵魂会打击20码内的所有敌人，造成相当于普通难度下普通敌人生命值3倍的伤害。', ''),
  (39, 'zhCN', '亡者复生雕文', '你击杀的精英会化为骷髅复生，为你而战20秒。最多同时存在5个。', '');
